# Nginx reverse proxy for a Node.js app on port 3000, with WebSocket support.
# Save as /etc/nginx/sites-available/app, link it into sites-enabled,
# then run: sudo nginx -t && sudo systemctl reload nginx
server {
    listen 80;
    server_name example.com;

    client_max_body_size 10m;

    gzip on;
    gzip_types text/plain text/css application/json application/javascript image/svg+xml;

    location / {
        proxy_pass http://127.0.0.1:3000;
        proxy_http_version 1.1;
        proxy_set_header Host $host;
        proxy_set_header X-Real-IP $remote_addr;
        proxy_set_header X-Forwarded-For $proxy_add_x_forwarded_for;
        proxy_set_header X-Forwarded-Proto $scheme;
        # WebSockets (Socket.io)
        proxy_set_header Upgrade $http_upgrade;
        proxy_set_header Connection "upgrade";
        proxy_read_timeout 60s;
    }
}

// fetch with timeout and retries (exponential backoff + jitter).
// Works in browsers and Node.js 18+. Retries network errors, 429 and 5xx.
//
//   import { fetchWithRetry } from './fetch-retry.mjs';
//   const response = await fetchWithRetry('https://api.github.com/zen');
//   console.log(await response.text());

const sleep = (ms) => new Promise((resolve) => setTimeout(resolve, ms));

export async function fetchWithRetry(url, options = {}, { retries = 3, baseDelay = 500, timeout = 10000 } = {}) {
  for (let attempt = 0; ; attempt++) {
    const controller = new AbortController();
    const timer = setTimeout(() => controller.abort(), timeout);
    try {
      const response = await fetch(url, { ...options, signal: controller.signal });
      const retryable = response.status === 429 || response.status >= 500;
      if (!retryable || attempt >= retries) return response;
      // Respect Retry-After (in seconds) when the server sends it
      const retryAfter = Number(response.headers.get('retry-after'));
      await sleep(retryAfter > 0 ? retryAfter * 1000 : backoff(attempt, baseDelay));
    } catch (error) {
      if (attempt >= retries) throw error;
      await sleep(backoff(attempt, baseDelay));
    } finally {
      clearTimeout(timer);
    }
  }
}

function backoff(attempt, baseDelay) {
  const exponential = baseDelay * 2 ** attempt;
  return exponential / 2 + Math.random() * (exponential / 2);
}

// Token-bucket rate limiter as Express middleware (no dependencies).
// Each client (by IP) can make `capacity` requests in a burst, refilled at
// `refillPerSecond`. Over the limit it answers 429 with a Retry-After header.
//
//   const express = require('express');
//   const rateLimit = require('./rate-limit');
//   const app = express();
//   app.use('/api', rateLimit({ capacity: 20, refillPerSecond: 5 }));

function rateLimit({ capacity = 20, refillPerSecond = 5, keyOf = (req) => req.ip } = {}) {
  const buckets = new Map();

  // Forget idle clients so memory does not grow forever
  setInterval(() => {
    const now = Date.now();
    for (const [key, bucket] of buckets) {
      if (now - bucket.updatedAt > 10 * 60 * 1000) buckets.delete(key);
    }
  }, 60 * 1000).unref();

  return function rateLimitMiddleware(req, res, next) {
    const key = keyOf(req);
    const now = Date.now();
    const bucket = buckets.get(key) || { tokens: capacity, updatedAt: now };
    bucket.tokens = Math.min(capacity, bucket.tokens + ((now - bucket.updatedAt) / 1000) * refillPerSecond);
    bucket.updatedAt = now;
    buckets.set(key, bucket);

    res.set('X-RateLimit-Limit', String(capacity));
    res.set('X-RateLimit-Remaining', String(Math.max(0, Math.floor(bucket.tokens - 1))));
    if (bucket.tokens < 1) {
      res.set('Retry-After', String(Math.ceil((1 - bucket.tokens) / refillPerSecond)));
      return res.status(429).json({ error: 'Too many requests' });
    }
    bucket.tokens -= 1;
    return next();
  };
}

module.exports = rateLimit;

// Dev Container: open the repo in GitHub Codespaces or VS Code (Dev Containers
// extension) with Node.js 20, the GitHub CLI and Docker ready to use.
// Save as .devcontainer/devcontainer.json
{
  "name": "Node.js",
  "image": "mcr.microsoft.com/devcontainers/javascript-node:1-20-bookworm",
  "features": {
    "ghcr.io/devcontainers/features/github-cli:1": {},
    "ghcr.io/devcontainers/features/docker-outside-of-docker:1": {}
  },
  "forwardPorts": [3000],
  "postCreateCommand": "npm ci",
  "customizations": {
    "vscode": {
      "extensions": ["dbaeumer.vscode-eslint", "esbenp.prettier-vscode", "github.vscode-github-actions"],
      "settings": {
        "editor.formatOnSave": true,
        "editor.defaultFormatter": "esbenp.prettier-vscode"
      }
    }
  }
}
